import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerViews() {
    const navigate = useNavigate();
    const [viewsData, setViewsData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [timeRange, setTimeRange] = useState('7days');

    useEffect(() => {
        loadViewsData();
    }, [timeRange]);

    const loadViewsData = async () => {
        try {
            setLoading(true);
            
            // In a real implementation, this would fetch actual views data
            // For now, we'll simulate with dummy data based on time range
            setTimeout(() => {
                let dummyData = [];
                
                if (timeRange === '7days') {
                    dummyData = [
                        { date: 'Mon', views: 1200, likes: 45, comments: 12 },
                        { date: 'Tue', views: 1800, likes: 67, comments: 18 },
                        { date: 'Wed', views: 950, likes: 32, comments: 8 },
                        { date: 'Thu', views: 2100, likes: 89, comments: 24 },
                        { date: 'Fri', views: 1650, likes: 56, comments: 15 },
                        { date: 'Sat', views: 2400, likes: 102, comments: 31 },
                        { date: 'Sun', views: 1980, likes: 78, comments: 22 }
                    ];
                } else if (timeRange === '30days') {
                    dummyData = [
                        { date: 'Week 1', views: 12500, likes: 450, comments: 120 },
                        { date: 'Week 2', views: 18700, likes: 670, comments: 180 },
                        { date: 'Week 3', views: 9800, likes: 320, comments: 85 },
                        { date: 'Week 4', views: 21500, likes: 890, comments: 240 }
                    ];
                } else {
                    dummyData = [
                        { date: 'Jan', views: 45000, likes: 1800, comments: 420 },
                        { date: 'Feb', views: 38000, likes: 1500, comments: 380 },
                        { date: 'Mar', views: 52000, likes: 2100, comments: 510 },
                        { date: 'Apr', views: 41000, likes: 1650, comments: 390 },
                        { date: 'May', views: 58000, likes: 2400, comments: 620 },
                        { date: 'Jun', views: 49000, likes: 1950, comments: 480 }
                    ];
                }
                
                setViewsData(dummyData);
                setLoading(false);
            }, 1000);
            
            // TODO: Implement actual API call to fetch views data
            /*
            const response = await ApiService.getSellerViews(timeRange);
            if (response.success) {
                setViewsData(response.data);
            } else {
                toast.error('Failed to load views data: ' + response.message);
            }
            */
        } catch (error) {
            console.error('Error loading views data:', error);
            toast.error('Failed to load views data: ' + error.message);
            setLoading(false);
        }
    };

    const handleBack = () => {
        navigate('/studio/seller/profile');
    };

    const handleTimeRangeChange = (range) => {
        setTimeRange(range);
    };

    const getTotalViews = () => {
        return viewsData.reduce((sum, item) => sum + item.views, 0);
    };

    const getTotalLikes = () => {
        return viewsData.reduce((sum, item) => sum + item.likes, 0);
    };

    const getTotalComments = () => {
        return viewsData.reduce((sum, item) => sum + item.comments, 0);
    };

    if (loading) {
        return (
            <div className="container-fluid">
                <div className="row">
                    <div className="col-12">
                        <div className="page-title-box d-flex align-items-center justify-content-between py-3">
                            <h4 className="mb-0">Views Analytics</h4>
                        </div>
                    </div>
                </div>
                <div className="row">
                    <div className="col-12">
                        <div className="card">
                            <div className="card-body text-center">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                                <p className="mt-2">Loading analytics data...</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container-fluid">
            <div className="row">
                <div className="col-12">
                    <div className="page-title-box d-flex align-items-center justify-content-between py-3">
                        <h4 className="mb-0">Views Analytics</h4>
                        <button className="btn btn-secondary" onClick={handleBack}>
                            <i className="mdi mdi-arrow-left me-1"></i>Back to Profile
                        </button>
                    </div>
                </div>
            </div>

            {/* Time Range Selector */}
            <div className="row">
                <div className="col-12">
                    <div className="card">
                        <div className="card-body">
                            <div className="d-flex flex-wrap gap-2">
                                <button 
                                    className={`btn ${timeRange === '7days' ? 'btn-primary' : 'btn-outline-primary'}`}
                                    onClick={() => handleTimeRangeChange('7days')}
                                >
                                    Last 7 Days
                                </button>
                                <button 
                                    className={`btn ${timeRange === '30days' ? 'btn-primary' : 'btn-outline-primary'}`}
                                    onClick={() => handleTimeRangeChange('30days')}
                                >
                                    Last 30 Days
                                </button>
                                <button 
                                    className={`btn ${timeRange === '6months' ? 'btn-primary' : 'btn-outline-primary'}`}
                                    onClick={() => handleTimeRangeChange('6months')}
                                >
                                    Last 6 Months
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Summary Cards */}
            <div className="row">
                <div className="col-md-4">
                    <div className="card bg-primary bg-opacity-10 border-primary border-opacity-25">
                        <div className="card-body">
                            <div className="d-flex align-items-center">
                                <div className="flex-shrink-0 bg-primary bg-opacity-25 rounded p-2">
                                    <i className="ri-eye-line ri-lg text-primary"></i>
                                </div>
                                <div className="flex-grow-1 ms-3">
                                    <h5 className="mb-1">{getTotalViews().toLocaleString()}</h5>
                                    <p className="mb-0 text-muted">Total Views</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="col-md-4">
                    <div className="card bg-success bg-opacity-10 border-success border-opacity-25">
                        <div className="card-body">
                            <div className="d-flex align-items-center">
                                <div className="flex-shrink-0 bg-success bg-opacity-25 rounded p-2">
                                    <i className="ri-thumb-up-line ri-lg text-success"></i>
                                </div>
                                <div className="flex-grow-1 ms-3">
                                    <h5 className="mb-1">{getTotalLikes().toLocaleString()}</h5>
                                    <p className="mb-0 text-muted">Total Likes</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="col-md-4">
                    <div className="card bg-info bg-opacity-10 border-info border-opacity-25">
                        <div className="card-body">
                            <div className="d-flex align-items-center">
                                <div className="flex-shrink-0 bg-info bg-opacity-25 rounded p-2">
                                    <i className="ri-chat-1-line ri-lg text-info"></i>
                                </div>
                                <div className="flex-grow-1 ms-3">
                                    <h5 className="mb-1">{getTotalComments().toLocaleString()}</h5>
                                    <p className="mb-0 text-muted">Total Comments</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Chart */}
            <div className="row">
                <div className="col-12">
                    <div className="card">
                        <div className="card-header">
                            <h5 className="mb-0">Views Overview - {timeRange === '7days' ? 'Daily' : timeRange === '30days' ? 'Weekly' : 'Monthly'}</h5>
                        </div>
                        <div className="card-body">
                            <div className="table-responsive">
                                <table className="table table-centered table-nowrap mb-0">
                                    <thead className="table-light">
                                        <tr>
                                            <th>Date</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Comments</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {viewsData.map((item, index) => (
                                            <tr key={index}>
                                                <td>{item.date}</td>
                                                <td>
                                                    <div className="d-flex align-items-center">
                                                        <span className="me-2">{item.views.toLocaleString()}</span>
                                                        <div className="progress flex-grow-1" style={{ height: '6px' }}>
                                                            <div 
                                                                className="progress-bar bg-primary" 
                                                                role="progressbar" 
                                                                style={{ width: `${(item.views / Math.max(...viewsData.map(d => d.views))) * 100}%` }}
                                                            ></div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="d-flex align-items-center">
                                                        <span className="me-2">{item.likes.toLocaleString()}</span>
                                                        <div className="progress flex-grow-1" style={{ height: '6px' }}>
                                                            <div 
                                                                className="progress-bar bg-success" 
                                                                role="progressbar" 
                                                                style={{ width: `${(item.likes / Math.max(...viewsData.map(d => d.likes))) * 100}%` }}
                                                            ></div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="d-flex align-items-center">
                                                        <span className="me-2">{item.comments.toLocaleString()}</span>
                                                        <div className="progress flex-grow-1" style={{ height: '6px' }}>
                                                            <div 
                                                                className="progress-bar bg-info" 
                                                                role="progressbar" 
                                                                style={{ width: `${(item.comments / Math.max(...viewsData.map(d => d.comments))) * 100}%` }}
                                                            ></div>
                                                        </div>
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
